Sketch the front, right-side and top views of this rectangular prism. The arrows show the viewing directions.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
% Solid: vertices A B C D at z=0; E F G H at z=3.
% Faces: ABCD, EFGH, ABFE, BCGF, CDHG, DAEH.
% Projection (x,y,z) -> (x+0.4z,y+0.25z); viewer (0.4,0.25,-1).
\coordinate (A) at (0,0); \coordinate (B) at (3.6,0); \coordinate (C) at (3.6,2.1); \coordinate (D) at (0,2.1);
\coordinate (E) at (1.2,0.75); \coordinate (F) at (4.8,0.75); \coordinate (G) at (4.8,2.85); \coordinate (H) at (1.2,2.85);
\draw (A)--(B)--(C)--(D)--cycle (B)--(F)--(G)--(C) (D)--(H)--(G);
\draw[dashed] (A)--(E)--(F) (E)--(H);
\draw[->] (1.8,-1.1)--(1.8,-0.25);
\path (1.8,-1.1) node[below] {Front};
\draw[->] (6,1.5)--(5.1,1.5);
\path (6,1.5) node[right] {Right side};
\draw[->] (2.8,4)--(2.8,3.15);
\path (2.8,4) node[above] {Top};
\end{tikzpicture}
[/tikz]

