examples.question_text:
Sketch each solid:
(a) a triangular prism;
(b) a cube;
(c) a pentagonal prism;
(d) a hexagonal prism.

examples.solution_text:
Draw a front face, then an identical face shifted behind it. Join matching corners with parallel edges. Use dashed lines for hidden edges. For the cube, all actual edges have equal length, although the depth edges appear shorter in the sketch.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
% Each model has its stated front polygon at z=0 and an identical rear polygon at z=2.
% Faces: both end polygons and one quadrilateral joining each corresponding pair of end edges.
% Projection (x,y,z) -> (x+0.45z,y+0.3z); viewer (0.45,0.3,-1).
\begin{scope}
\draw (0,0)--(2.4,0)--(1.2,1.8)--cycle;
\draw (2.4,0)--(3.3,0.6)--(2.1,2.4)--(1.2,1.8);
\draw[dashed] (0,0)--(0.9,0.6)--(3.3,0.6) (0.9,0.6)--(2.1,2.4);
\path (1.65,-0.35) node[below] {(a) Triangular prism};
\end{scope}
\begin{scope}[shift={(5,0)}]
% Cube front width=height=depth=2.
\draw (0,0) rectangle (2,2);
\draw (2,0)--(2.9,0.6)--(2.9,2.6)--(2,2) (0,2)--(0.9,2.6)--(2.9,2.6);
\draw[dashed] (0,0)--(0.9,0.6)--(2.9,0.6) (0.9,0.6)--(0.9,2.6);
\path (1.45,-0.35) node[below] {(b) Cube};
\end{scope}
\begin{scope}[shift={(0,-4.6)}]
% Front pentagon (0,0),(2.4,0),(2.4,1.3),(1.2,2.2),(0,1.3).
% The upper-right and right vertical lateral faces face the viewer; the upper-left lateral face faces away.
% Upper-left outward normal (-0.9,1.2,0) has viewer dot product -0.045.
% Its rear upper-left edge and left connector are hidden; the front upper-left edge remains visible.
\draw (0,0)--(2.4,0)--(2.4,1.3)--(1.2,2.2)--(0,1.3)--cycle;
\draw (2.4,0)--(3.3,0.6)--(3.3,1.9)--(2.1,2.8);
\draw (2.4,1.3)--(3.3,1.9) (1.2,2.2)--(2.1,2.8);
\draw[dashed] (0,0)--(0.9,0.6)--(3.3,0.6) (0.9,0.6)--(0.9,1.9) (2.1,2.8)--(0.9,1.9)--(0,1.3);
\path (1.65,-0.35) node[below] {(c) Pentagonal prism};
\end{scope}
\begin{scope}[shift={(5,-4.6)}]
% Front hexagon (0,1),(0.6,0),(2,0),(2.6,1),(2,2),(0.6,2).
\draw (0,1)--(0.6,0)--(2,0)--(2.6,1)--(2,2)--(0.6,2)--cycle;
\draw (2,0)--(2.9,0.6)--(3.5,1.6)--(2.9,2.6)--(1.5,2.6)--(0.6,2);
\draw (2.6,1)--(3.5,1.6) (2,2)--(2.9,2.6);
\draw[dashed] (0,1)--(0.9,1.6)--(1.5,0.6)--(2.9,0.6) (0.6,0)--(1.5,0.6) (0.9,1.6)--(1.5,2.6);
\path (1.75,-0.35) node[below] {(d) Hexagonal prism};
\end{scope}
\end{tikzpicture}
[/tikz]

