examples.solution_text:
Keep each end shape unchanged and join matching corners. These sketches show visible edges only.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
% Concave prisms: listed front polygons at z=0, identical rear polygons at z=2.
% Faces: both end polygons and corresponding lateral quadrilaterals.
% Projection (x,y,z) -> (x+0.4z,y+0.3z); viewer (0.4,0.3,-1).
% Hidden edges omitted; exposed segments derived from the front polygon's occlusion.
\draw (0,0)--(3.4,0)--(3.4,1.1)--(1.3,1.1)--(1.3,3)--(0,3)--cycle;
\draw (3.4,0)--(4.2,0.6)--(4.2,1.7)--(3.4,1.1);
\draw (1.3,1.1)--(2.1,1.7)--(4.2,1.7);
\draw (1.3,3)--(2.1,3.6)--(2.1,1.7);
\draw (0,3)--(0.8,3.6)--(2.1,3.6);
\path (2.1,-0.3) node[below] {(a)};
\begin{scope}[shift={(6,0)}]
\draw (0,0)--(4.2,0)--(4.2,1.1)--(2.8,1.1)--(2.8,2.7)--(1.4,2.7)--(1.4,1.1)--(0,1.1)--cycle;
\draw (4.2,0)--(5,0.6)--(5,1.7)--(4.2,1.1);
\draw (2.8,1.1)--(3.6,1.7)--(5,1.7);
\draw (2.8,2.7)--(3.6,3.3)--(3.6,1.7);
\draw (1.4,2.7)--(2.2,3.3)--(3.6,3.3);
\draw (0,1.1)--(0.8,1.7)--(1.4,1.7);
\path (2.5,-0.3) node[below] {(b)};
\end{scope}
\end{tikzpicture}
[/tikz]
