examples.solution_text:
The front view gives the height, $4\,\mathrm{m}$. The top view gives the width, $5\,\mathrm{m}$. The side view gives the depth, $7\,\mathrm{m}$. Draw matching rectangular ends and label those directions.
[tikz]
\begin{tikzpicture}[x=10mm,y=10mm,draw=black,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
% Model dimensions: width 5, height 4, depth 7; uniform scale factor 0.5.
% Vertices A B C D at z=0; E F G H at z=3.5.
% Faces: ABCD, EFGH, ABFE, BCGF, CDHG, DAEH.
% Projection (x,y,z) -> (x+0.3z,y+0.2z); viewer (0.3,0.2,-1).
\coordinate (A) at (0,0); \coordinate (B) at (2.5,0); \coordinate (C) at (2.5,2); \coordinate (D) at (0,2);
\coordinate (E) at (1.05,0.7); \coordinate (F) at (3.55,0.7); \coordinate (G) at (3.55,2.7); \coordinate (H) at (1.05,2.7);
\draw (A)--(B)--(C)--(D)--cycle (B)--(F)--(G)--(C) (D)--(H)--(G);
\draw[dashed] (A)--(E)--(F) (E)--(H);
\path (1.25,0) node[below] {$5\,\mathrm{m}$};
\path (0,1) node[left] {$4\,\mathrm{m}$};
\path (3.025,0.35) node[below right] {$7\,\mathrm{m}$};
\end{tikzpicture}
[/tikz]
